function fewestLaneChanges(cones: number[]): number {
  const n = cones.length - 1;
  const dist = new Array(3 * (n + 1)).fill(Infinity);
  // state id = point * 3 + (lane - 1); the deque is an array with a moving head
  const dq: number[] = new Array(12 * (n + 1) + 4);
  let head = 6 * (n + 1), tail = head;
  dist[1] = 0;
  dq[tail++] = 1;
  while (head < tail) {
    const s = dq[head++], p = Math.floor(s / 3), lane = s % 3, d = dist[s];
    if (p === n) return d;
    const fwd = s + 3;
    if (cones[p + 1] !== lane + 1 && d < dist[fwd]) { dist[fwd] = d; dq[--head] = fwd; }
    for (let other = 0; other < 3; other++) {
      const t = p * 3 + other;
      if (other !== lane && cones[p] !== other + 1 && d + 1 < dist[t]) { dist[t] = d + 1; dq[tail++] = t; }
    }
  }
  return -1;
}

