class Solution:
    def fewestLaneChanges(self, cones: List[int]) -> int:
        n = len(cones) - 1
        INF = float("inf")
        dist = [[INF] * 3 for _ in range(n + 1)]
        dist[0][1] = 0
        dq = deque([(0, 1)])
        while dq:
            p, lane = dq.popleft()
            d = dist[p][lane]
            if p == n:
                return d
            if cones[p + 1] != lane + 1 and d < dist[p + 1][lane]:
                dist[p + 1][lane] = d
                dq.appendleft((p + 1, lane))
            for other in range(3):
                if other != lane and cones[p] != other + 1 and d + 1 < dist[p][other]:
                    dist[p][other] = d + 1
                    dq.append((p, other))
        return -1

