function fewestLaneChanges(cones: number[]): number {
  const best = [1, 0, 1];
  for (let i = 1; i < cones.length; i++) {
    const blocked = cones[i] - 1; // -1 when the point is clear
    if (blocked >= 0) best[blocked] = Infinity;
    const m = Math.min(best[0], best[1], best[2]);
    for (let lane = 0; lane < 3; lane++) {
      if (lane !== blocked) best[lane] = Math.min(best[lane], m + 1);
    }
  }
  return Math.min(best[0], best[1], best[2]);
}

